class Solution {
    public int[] spiralOrder(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] seen = new boolean[m][n];
        int[] dr = {0, 1, 0, -1}, dc = {1, 0, -1, 0};
        int r = 0, c = 0, d = 0;
        int[] out = new int[m * n];
        for (int k = 0; k < m * n; k++) {
            out[k] = grid[r][c];
            seen[r][c] = true;
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr][nc]) d = (d + 1) % 4;
            r += dr[d];
            c += dc[d];
        }
        return out;
    }
}

