int* spiralOrder(int** grid, int gridSize, int* gridColSize, int* returnSize) {
    int m = gridSize, n = gridColSize[0];
    bool* seen = calloc(m * n, sizeof(bool));
    int dr[] = {0, 1, 0, -1}, dc[] = {1, 0, -1, 0};
    int r = 0, c = 0, d = 0;
    int* out = malloc(m * n * sizeof(int));
    for (int k = 0; k < m * n; k++) {
        out[k] = grid[r][c];
        seen[r * n + c] = true;
        int nr = r + dr[d], nc = c + dc[d];
        if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr * n + nc]) d = (d + 1) % 4;
        r += dr[d];
        c += dc[d];
    }
    free(seen);
    *returnSize = m * n;
    return out;
}

