class Solution {
    public int[] spiralOrder(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        int[] out = new int[m * n];
        int k = 0;
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++) out[k++] = grid[top][c];
            top++;
            for (int r = top; r <= bottom; r++) out[k++] = grid[r][right];
            right--;
            if (top <= bottom) {
                for (int c = right; c >= left; c--) out[k++] = grid[bottom][c];
                bottom--;
            }
            if (left <= right) {
                for (int r = bottom; r >= top; r--) out[k++] = grid[r][left];
                left++;
            }
        }
        return out;
    }
}

